def parse_rdb_data(rdb_text):
    """Parse USGS RDB format and extract streamflow values"""
    if not rdb_text:
        return []

    values = []
    lines = rdb_text.strip().split('\n')
    data_start = False

    for line in lines:
        if line.startswith('#') or line.startswith('USGS'):
            continue
        if line.startswith('agency_cd'):
            data_start = True
            continue
        if line.startswith('5s'):
            continue
        if not data_start or not line.strip():
            continue

        parts = line.split('\t')
        if len(parts) >= 4:
            try:
                streamflow = float(parts[3])
                values.append(streamflow)
            except (ValueError, IndexError):
                continue

    return values

